import{_ as d,o,c as u,ag as q}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"按模型索引金句","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/quote-按模型索引.md","filePath":"40-原话金句/quote-按模型索引.md","lastUpdated":1778031108000}'),r={name:"40-原话金句/quote-按模型索引.md"};function e(a,t,h,l,b,i){return o(),u("div",null,[...t[0]||(t[0]=[q('<h1 id="按模型索引金句" tabindex="-1">按模型索引金句 <a class="header-anchor" href="#按模型索引金句" aria-label="Permalink to &quot;按模型索引金句&quot;">​</a></h1><blockquote><p>按七大核心模型组织的金句索引 每条金句标注来源经典</p></blockquote><hr><h2 id="一、天人合一" tabindex="-1">一、天人合一 <a class="header-anchor" href="#一、天人合一" aria-label="Permalink to &quot;一、天人合一&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>金句</th><th>来源</th></tr></thead><tbody><tr><td>1</td><td>&quot;观天之道，执天之行——观察大自然的规律，并以此规范我们的行为。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>2</td><td>&quot;一滴水与大海融为一体——到底是大海得到一滴水，还是一滴水得到了大海？&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>3</td><td>&quot;宇宙的能量场有无穷无尽的频道，我们通过修行慢慢与更多的场同步共振。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>4</td><td>&quot;天性人也——真正的标准的人要与天地一样的性质。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>5</td><td>&quot;人法地，地法天，天法道，道法自然。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>6</td><td>&quot;佛说非身，是名大身——真正的&#39;大&#39;是跟宇宙一样大。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>7</td><td>&quot;万法皆空，因果不空——因果的规律不会因为死亡而中断。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>8</td><td>&quot;道无处不在。大到宇宙星辰，小到一草一木，都在道中。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr></tbody></table><hr><h2 id="二、对境不住" tabindex="-1">二、对境不住 <a class="header-anchor" href="#二、对境不住" aria-label="Permalink to &quot;二、对境不住&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>金句</th><th>来源</th></tr></thead><tbody><tr><td>1</td><td>&quot;保持平静的要诀就是保持理智地去看待一切。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>2</td><td>&quot;过去心不可得，现在心不可得，未来心不可得。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>3</td><td>&quot;凡所有相，皆是虚妄——不是没有相，而是所有的相都是不永恒的。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>4</td><td>&quot;若见诸相非相，即见如来——看到一切现象都不是永恒的，你就见到真相了。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>5</td><td>&quot;应无所住而生其心——心不要停在任何一个地方。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>6</td><td>&quot;知见无见，斯即涅槃——知道各种观点，但不执着于任何观点。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>7</td><td>&quot;不平静时问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>8</td><td>&quot;不怕念起，只怕觉迟。走神了，知道走神就不走神。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>9</td><td>&quot;烦恼来了，不是压制它，也不是随它去。看清楚它，然后做该做的事。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>10</td><td>&quot;照见五蕴皆空——清清楚楚地明白色受想行识都是不永恒的。&quot;</td><td>[心经](/40-原话金句/quote-心经)</td></tr><tr><td>11</td><td>&quot;色不异空，空不异色——物质和空不是两回事。&quot;</td><td>[心经](/40-原话金句/quote-心经)</td></tr><tr><td>12</td><td>&quot;被人骂时，试着用旁观者的心态——&#39;他为什么这么激动？&#39;而不是&#39;他在骂我！&#39;&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr></tbody></table><hr><h2 id="三、对法不执" tabindex="-1">三、对法不执 <a class="header-anchor" href="#三、对法不执" aria-label="Permalink to &quot;三、对法不执&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>金句</th><th>来源</th></tr></thead><tbody><tr><td>1</td><td>&quot;法尚应舍，何况非法——连佛法都要放下，何况那些不是法的东西。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>2</td><td>&quot;所谓佛法者，即非佛法——佛祖说的种种方法是对症下药，药方不能通用。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>3</td><td>&quot;庄严佛土者，即非庄严，是名庄严——做好事是自然的流露，不是求功德。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>4</td><td>&quot;无有定法名阿耨多罗三藐三菩提——没有一个固定的方法叫做开悟。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>5</td><td>&quot;雷锋帮完人就走了，不等着对方说谢谢。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>6</td><td>&quot;以无我无人无众生无寿者修一切善法，即得阿耨多罗三藐三菩提。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>7</td><td>&quot;实无有法名阿罗汉——不觉得自己证得了什么，才是真正的证得。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>8</td><td>&quot;不应取法，不应取非法——不能执着于方法，也不能执着于&#39;一切都是空的&#39;。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>9</td><td>&quot;法无定法，各人因缘不同。千万不要拿自己的法门去评判别人的。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>10</td><td>&quot;做完了就放下。不要做完一件事还在想&#39;我做得好不好&#39;。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>11</td><td>&quot;你若真的放下了，就不需要说&#39;我放下了&#39;。说出来的时候，其实还没放下。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>12</td><td>&quot;通达无我法——不是什么都不做。不做事是惰性，不是通达。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr></tbody></table><hr><h2 id="四、自然务实" tabindex="-1">四、自然务实 <a class="header-anchor" href="#四、自然务实" aria-label="Permalink to &quot;四、自然务实&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>金句</th><th>来源</th></tr></thead><tbody><tr><td>1</td><td>&quot;无为不是什么都不做，是无妄为——不违背客观规律去乱搞。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>2</td><td>&quot;凡事尽力而为，做人问心无愧。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>3</td><td>&quot;因上精进，果上随缘——过程努力，结果不执着。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>4</td><td>&quot;做就是了。行动胜过千言万语。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>5</td><td>&quot;天下难事必作于易，天下大事必作于细。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>6</td><td>&quot;千里之行，始于足下——走起来最重要了！&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>7</td><td>&quot;学东西不要追求&#39;学完&#39;，追求&#39;用上一条就赚一条&#39;。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>8</td><td>&quot;一切贤圣，皆以无为法而有差别——方法有快慢，但都是为了到彼岸。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>9</td><td>&quot;少则得，多则惑——想要得太多，反而什么都得不到。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>10</td><td>&quot;做一件事之前，先问自己：目的是什么？方法是什么？&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>11</td><td>&quot;有些事想不通，不要硬想。先放下，去做点别的，答案自然会浮现。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>12</td><td>&quot;有之以为利，无之以为用——杯子中间空的地方才能装水。要&#39;放空&#39;。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr></tbody></table><hr><h2 id="五、圆融中和" tabindex="-1">五、圆融中和 <a class="header-anchor" href="#五、圆融中和" aria-label="Permalink to &quot;五、圆融中和&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>金句</th><th>来源</th></tr></thead><tbody><tr><td>1</td><td>&quot;多言数穷，不如守中——话说多了反而说不清楚，不如保持内心清净。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>2</td><td>&quot;守中不是停在中间不动，是不走极端。就像开车，要不断微调方向。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>3</td><td>&quot;上善若水——最高的善像水一样，善利万物而不争。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>4</td><td>&quot;整体观定善恶——把整个事情的前因后果都看清楚。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>5</td><td>&quot;不与取法不应取非法——吃药好了就不吃了，病没好也不能不吃。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>6</td><td>&quot;顺境不沉溺，逆境不气馁——保持平常心。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>7</td><td>&quot;天之道，损有余而补不足——自然的规律是减少多余的去补充不足的。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>8</td><td>&quot;夫唯不争，故天下莫能与之争。&quot;</td><td>[道德经](/40-原话金句/quote-道德经)</td></tr><tr><td>9</td><td>&quot;心无挂碍——心里没有牵挂和障碍。&quot;</td><td>[心经](/40-原话金句/quote-心经)</td></tr><tr><td>10</td><td>&quot;远离颠倒梦想，究竟涅槃——把颠倒了的人生观转过来。&quot;</td><td>[心经](/40-原话金句/quote-心经)</td></tr><tr><td>11</td><td>&quot;不批判别人，不苛求自己。该做的事去做，不该做的事不做。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>12</td><td>&quot;若真修道人，不见世间过——看到别人的过错，心里不因此起烦恼。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr></tbody></table><hr><h2 id="六、历境炼心" tabindex="-1">六、历境炼心 <a class="header-anchor" href="#六、历境炼心" aria-label="Permalink to &quot;六、历境炼心&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>金句</th><th>来源</th></tr></thead><tbody><tr><td>1</td><td>&quot;烦恼即菩提——烦恼不是敌人，它是你修行的机会。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>2</td><td>&quot;家庭是道场，工作单位是道场，社会是道场。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>3</td><td>&quot;修行就是历境炼心——在每一个具体的境遇中磨炼自己的心。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>4</td><td>&quot;一切法皆是佛法——只要不执着，一切现象都能成为觉悟的契机。&quot;</td><td>[金刚经](/40-原话金句/quote-金刚经)</td></tr><tr><td>5</td><td>&quot;冤亲平等——对伤害你的人和对帮助你的人，保持同样的心。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>6</td><td>&quot;顺逆皆修——顺利时要修（不骄傲），逆境时要修（不气馁）。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>7</td><td>&quot;病来了不要怕，看它是什么病，该吃药吃药。同时保持心灵的平静。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>8</td><td>&quot;遇到事情，先停三秒，深呼吸，再说话、再行动。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>9</td><td>&quot;有人对不起你，你原谅他，不是因为你懦弱，是因为你大气。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>10</td><td>&quot;能除一切苦，真实不虚——真正明白了诸法空相，很多痛苦自然解脱了。&quot;</td><td>[心经](/40-原话金句/quote-心经)</td></tr><tr><td>11</td><td>&quot;人生就是一场修行，遇到的每一个人、每一件事，都是来度你的。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>12</td><td>&quot;忍辱不是憋着，是看破、放下。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr></tbody></table><hr><h2 id="七、性命双修" tabindex="-1">七、性命双修 <a class="header-anchor" href="#七、性命双修" aria-label="Permalink to &quot;七、性命双修&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>金句</th><th>来源</th></tr></thead><tbody><tr><td>1</td><td>&quot;不可用心守，不可无意求——守得太紧就着相，守得太松就无效。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>2</td><td>&quot;似守非守——轻轻知道，轻轻放下。在有心无心之间。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>3</td><td>&quot;但安神息，不运火而火自运——心平气和了，一切自自然然。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>4</td><td>&quot;百日功灵，必有变化——坚持一百天，身体一定会有变化。十月胎圆，功夫更深。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>5</td><td>&quot;行住坐卧，绵绵若存——随时保持一种轻轻返观身体的状态。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>6</td><td>&quot;神守黄房，金胎自成——黄房就是中丹田，轻轻观照中丹田。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>7</td><td>&quot;静坐时杂念来了，看着它，不跟随，不攀缘，它自然就消失了。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>8</td><td>&quot;不要追求感觉。有感觉是正常的，没感觉也是正常的。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>9</td><td>&quot;静坐姿势中正安舒，不要硬撑。双盘、单盘、散盘、坐椅子都可以。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>10</td><td>&quot;与人为善，观察自己的念头。做到这两点，一切都在其中。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>11</td><td>&quot;愿力决定层次，魄力决定成就——你的愿有多大，功夫就能走多远。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>12</td><td>&quot;形神俱妙——身体与精神都达到妙境，二者俱佳。&quot;</td><td>[中论丹道](/40-原话金句/quote-中论丹道)</td></tr><tr><td>13</td><td>&quot;修行的目的是明心见性，不是神通。神通是副产品。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr><tr><td>14</td><td>&quot;开悟不是毕业，开悟是入学了。悟后起修才是真正的修行。&quot;</td><td>[答疑精选](/40-原话金句/quote-答疑精选)</td></tr></tbody></table><hr><blockquote><p>整理日期：2026-05-06</p></blockquote>',25)])])}const c=d(r,[["render",e]]);export{s as __pageData,c as default};
